import{_ as e,o as t,c as a,af as r}from"./chunks/framework.Dt3O48XQ.js";const m=JSON.parse('{"title":"应用场景（概览）","description":"","frontmatter":{},"headers":[],"relativePath":"scenarios/overview.md","filePath":"scenarios/overview.md","lastUpdated":null}'),i={name:"scenarios/overview.md"};function c(s,o,n,d,h,l){return t(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="应用场景-概览" tabindex="-1">应用场景（概览） <a class="header-anchor" href="#应用场景-概览" aria-label="Permalink to &quot;应用场景（概览）&quot;">​</a></h1><p>按你的玩法 <strong>直接跳对应文档</strong>；每条下面链到站内说明（客户端 / 服务端 / 运维各取所需）。</p><h2 id="实时多人对战与帧同步" tabindex="-1">实时多人对战与帧同步 <a class="header-anchor" href="#实时多人对战与帧同步" aria-label="Permalink to &quot;实时多人对战与帧同步&quot;">​</a></h2><p>适合 MOBA、格斗、横版过关等对 <strong>操作一致性</strong> 要求高的玩法。</p><ul><li><strong>能力</strong>：<code>game_room</code> + <a href="/xcs.github.io/rooms/frame-sync-game-room.html">帧同步与游戏房</a>，固定帧率收集 <code>input</code>、Schema 状态同步，支持匹配下发的座位与 <a href="/xcs.github.io/rooms/frame-sync-game-room.html">断线重连</a>。</li><li><strong>客户端</strong>：任选 <a href="/xcs.github.io/engine/unity.html">Unity</a>、<a href="/xcs.github.io/engine/cocos-creator.html">Cocos Creator</a>、<a href="/xcs.github.io/engine/godot.html">Godot</a> 等，按官方 SDK 接入后再绑定本项目 JWT。</li><li><strong>文档侧重</strong>：服务端消息名与房间契约；客户端预测 / 回滚在引擎侧实现。</li></ul><h3 id="格斗游戏帧同步-专项" tabindex="-1">格斗游戏帧同步（专项） <a class="header-anchor" href="#格斗游戏帧同步-专项" aria-label="Permalink to &quot;格斗游戏帧同步（专项）&quot;">​</a></h3><p><strong>1v1 / 小人数格斗</strong>：独立 <strong><code>modeId</code></strong>（如 <code>fighting_1v1</code>）、<strong><code>playersPerMatch: 2</code></strong>，在 <strong><code>input.inputs</code></strong> 中约定方向与按键位掩码；框架负责帧 Tick 与房间契约，<strong>判定与手感在您侧实现</strong>。步骤与示例见：<a href="/xcs.github.io/scenarios/fighting-game-frame-sync.html">格斗游戏帧同步</a>。</p><h2 id="匹配大厅与房间码组队" tabindex="-1">匹配大厅与房间码组队 <a class="header-anchor" href="#匹配大厅与房间码组队" aria-label="Permalink to &quot;匹配大厅与房间码组队&quot;">​</a></h2><p>适合「一键匹配路人」或「好友输入房间码组队开局」。</p><ul><li><strong>能力</strong>：<a href="/xcs.github.io/rooms/matchmaking.html">匹配与开房</a> 中的 <code>matchmaker_room</code>：主动排队 <code>match:find</code>、取消 <code>match:cancel</code>，以及 Party <code>party:create</code> / <code>party:join</code> / <code>party:start</code>；组局成功后进入 <code>game_room</code>。</li><li><strong>依赖</strong>：<strong>Redis</strong>（本地跑通请先起 Redis）。</li><li><strong>客户端</strong>：登录拿 JWT → 进 <code>matchmaker_room</code> → 收 <code>match:found</code> → <code>joinById</code> 进 <code>game_room</code>（步骤见 <a href="/xcs.github.io/rooms/matchmaking.html">匹配与开房</a>）。</li></ul><h3 id="组队下副本-队伍聊天-专项" tabindex="-1">组队下副本 + 队伍聊天（专项） <a class="header-anchor" href="#组队下副本-队伍聊天-专项" aria-label="Permalink to &quot;组队下副本 + 队伍聊天（专项）&quot;">​</a></h3><p>被动开房（房间码 Party）与 <strong><code>chat_team_room</code></strong> 组合：等人、打字沟通、房主开局进 <code>game_room</code>。步骤、消息与 <strong>TypeScript 示例代码</strong> 见：<a href="/xcs.github.io/scenarios/party-dungeon-team-chat.html">组队下副本：被动开房（Party）+ 队伍聊天</a>。</p><h3 id="多-v-多自动匹配-多模式-×-动态人数" tabindex="-1">多 V 多自动匹配（多模式 × 动态人数） <a class="header-anchor" href="#多-v-多自动匹配-多模式-×-动态人数" aria-label="Permalink to &quot;多 V 多自动匹配（多模式 × 动态人数）&quot;">​</a></h3><p>同一套 <code>matchmaker_room</code>：改 <strong><code>modeId</code> / <code>playersPerMatch</code> / <code>region</code></strong> 即可支持 2 人、4 人、10 人、行会场等。<strong>浏览器演示 + 参数速查</strong> 见：<a href="/xcs.github.io/scenarios/multi-scale-matchmaking.html">多 V 多自动匹配</a>。</p><h2 id="世界-工会-附近-队伍聊天" tabindex="-1">世界 / 工会 / 附近 / 队伍聊天 <a class="header-anchor" href="#世界-工会-附近-队伍聊天" aria-label="Permalink to &quot;世界 / 工会 / 附近 / 队伍聊天&quot;">​</a></h2><p>适合 MMO-like 社交、公会频道、小队语音文字配套、地图附近可见聊天。</p><ul><li><strong>能力</strong>：四类聊天房间（<code>chat_world_room</code> 等），世界频道支持 <strong>Redis Pub/Sub</strong> 跨进程同步（见 <a href="/xcs.github.io/rooms/messages.html">多模式聊天</a>、<a href="/xcs.github.io/reference/protocol.html">消息协议</a>）。</li><li><strong>参数</strong>：进房 options 中带 <code>guildId</code>、<code>teamId</code>、坐标与 <code>nearbyRadius</code> 等；消息 <code>chat</code>、<code>updatePosition</code>（附近）。</li><li><strong>鉴权</strong>：与业务房间一致，需 <a href="/xcs.github.io/guide/jwt-room-auth.html">JWT 与房间鉴权</a>。</li></ul><h2 id="微信-抖音小游戏登录与账号体系" tabindex="-1">微信 / 抖音小游戏登录与账号体系 <a class="header-anchor" href="#微信-抖音小游戏登录与账号体系" aria-label="Permalink to &quot;微信 / 抖音小游戏登录与账号体系&quot;">​</a></h2><p>适合小程序渠道获客、与站内用户表打通。</p><ul><li><strong>能力</strong>：<code>GET /api/minigame/weixin/login</code>、<code>douyin/login</code> 换平台票据并 <strong>findOrCreate</strong> 本地用户，返回 <strong><code>token</code> + <code>user</code></strong>（不含密码）；JWT <code>userId</code> 为库主键。</li><li><strong>文档</strong>：<a href="/xcs.github.io/reference/minigame/weixin.html">微信小游戏登录</a>、<a href="/xcs.github.io/reference/minigame/douyin.html">抖音小游戏登录</a>、<a href="/xcs.github.io/reference/api.html">API 概览</a>。</li><li><strong>衔接</strong>：小游戏拿到的 access token 与账号密码登录一样，用于 Colyseus 进房 <code>token</code> 字段。</li></ul><h2 id="http-api-实时房间混合架构" tabindex="-1">HTTP API + 实时房间混合架构 <a class="header-anchor" href="#http-api-实时房间混合架构" aria-label="Permalink to &quot;HTTP API + 实时房间混合架构&quot;">​</a></h2><p>适合「大厅与支付走 HTTP，战斗走 WebSocket」的常见手游架构。</p><ul><li><strong>能力</strong>：Express + <strong>routing-controllers</strong>（Swagger）、JWT；Colyseus 专注房间与状态。</li><li><strong>文档</strong>：<a href="/xcs.github.io/reference/api.html">API 概览</a>、<a href="/xcs.github.io/guide/jwt-room-auth.html">JWT 与房间鉴权</a>、<a href="/xcs.github.io/guide/project-structure.html">项目结构</a>。</li><li><strong>注意</strong>：HTTP <code>Bearer</code> 与房间 <code>@RequireAuth</code> 的 Redis 校验策略不完全相同，关键路径以文档为准。</li></ul><h2 id="压测、演示与二次开发基线" tabindex="-1">压测、演示与二次开发基线 <a class="header-anchor" href="#压测、演示与二次开发基线" aria-label="Permalink to &quot;压测、演示与二次开发基线&quot;">​</a></h2><ul><li><strong>压测</strong>：<code>loadtest_room</code>（无 JWT，仅测试）与 <code>loadtest/</code> 脚本；生产关闭与环境变量说明见 <a href="/xcs.github.io/ops/load-testing.html">人数压力测</a>。</li><li><strong>演示</strong>：<code>my_room</code> 可作为最小房间模板；Playground / Monitor 便于开发期调试（生产勿暴露 Playground）。</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>入口</th></tr></thead><tbody><tr><td>房间与协议全集</td><td><a href="/xcs.github.io/rooms/overview.html">房间机制概览</a>、<a href="/xcs.github.io/reference/protocol.html">消息协议</a></td></tr><tr><td>部署与多实例 / 压测</td><td><a href="/xcs.github.io/ops/deployment.html">部署说明</a>、<a href="/xcs.github.io/ops/load-testing.html">人数压力测</a>、匹配文档中的 Redis 说明</td></tr><tr><td>从零搭建环境</td><td><a href="/xcs.github.io/guide/installation.html">安装指南</a>、<a href="/xcs.github.io/guide/configuration.html">配置说明</a></td></tr></tbody></table>',27)])])}const u=e(i,[["render",c]]);export{m as __pageData,u as default};
